style.css:
@-moz-document domain("youtube.com") {
/* 1. Hide the default YouTube logo icon (the red play button) */
    #logo-icon-container #logo-icon,
    #logo-icon {
        display: none !important;
        visibility: hidden !important;
    }

    /* 2. Hide the default "YouTube" text next to the icon */
    #logo-icon-container #logo-text {
        display: none !important;
        visibility: hidden !important;
    }

    /* 3. Apply the custom image to the main logo container */
    a#logo,
    ytd-topbar-renderer #logo-icon-container {
        /* Your direct image link */
        background-image: url("https://i.imgur.com/qJxCTHc.png") !important; 
        
        /* Default dimensions for the YouTube logo space */
        width: 250px !important; 
        height: 70px !important;  
        
        /* Ensure the image displays correctly */
        background-repeat: no-repeat !important;
        background-position: left center !important; 
        background-size: contain !important; 
        
        /* Ensure the container is visible */
        display: block !important;
        opacity: 1 !important;
    }
}
